import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  fieldControlClasses,
  fieldDescriptionClasses,
  fieldErrorClasses,
  fieldItemClasses,
  fieldLabelClasses,
  fieldRootClasses,
  fieldValidityClasses,
} from "./view";

export {
  fieldControlClasses,
  fieldDescriptionClasses,
  fieldErrorClasses,
  fieldItemClasses,
  fieldLabelClasses,
  fieldRootClasses,
  fieldValidityClasses,
} from "./view";

export type FieldStyle = Readonly<Record<string, string>>;

export type FieldState = Readonly<{
  disabled?: boolean | undefined;
  required?: boolean | undefined;
  invalid?: boolean | undefined;
  dirty?: boolean | undefined;
  touched?: boolean | undefined;
  filled?: boolean | undefined;
  focused?: boolean | undefined;
}>;

export type RootViewConfig = FieldState &
  Readonly<{
    children: readonly Html[];
    name?: string | undefined;
    classes?: string | undefined;
    style?: FieldStyle | undefined;
  }>;

export type LabelViewConfig = Readonly<{
  children: readonly Html[];
  forId?: string | undefined;
  classes?: string | undefined;
  style?: FieldStyle | undefined;
}>;

export type ControlViewConfig<ParentMessage> = FieldState &
  Readonly<{
    id: string;
    value: string;
    onInput: (value: string) => ParentMessage;
    describedByIds?: readonly string[] | undefined;
    ariaLabel?: string | undefined;
    name?: string | undefined;
    placeholder?: string | undefined;
    type?: string | undefined;
    classes?: string | undefined;
    style?: FieldStyle | undefined;
  }>;

export type DescriptionViewConfig = Readonly<{
  id?: string | undefined;
  children: readonly Html[];
  classes?: string | undefined;
  style?: FieldStyle | undefined;
}>;

export type ErrorViewConfig = Readonly<{
  id?: string | undefined;
  children: readonly Html[];
  show: boolean;
  classes?: string | undefined;
  style?: FieldStyle | undefined;
}>;

export type ItemViewConfig = Readonly<{
  children: readonly Html[];
  classes?: string | undefined;
  style?: FieldStyle | undefined;
}>;

const cn = (base: string, classes?: string): string =>
  [base, classes]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const stateAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  state: FieldState
) => [
  ...(state.disabled === true ? [h.DataAttribute("disabled", "")] : []),
  ...(state.required === true ? [h.DataAttribute("required", "")] : []),
  ...(state.invalid === true ? [h.DataAttribute("invalid", "")] : []),
  ...(state.invalid === false ? [h.DataAttribute("valid", "")] : []),
  ...(state.dirty === true ? [h.DataAttribute("dirty", "")] : []),
  ...(state.touched === true ? [h.DataAttribute("touched", "")] : []),
  ...(state.filled === true ? [h.DataAttribute("filled", "")] : []),
  ...(state.focused === true ? [h.DataAttribute("focused", "")] : []),
];

export const rootView = <ParentMessage>({
  children,
  name,
  classes,
  style,
  ...state
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(name === undefined ? [] : [h.DataAttribute("name", name)]),
      ...stateAttributes(h, state),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(fieldRootClasses, classes)),
    ],
    children
  );
};

export const labelView = <ParentMessage>({
  children,
  forId,
  classes,
  style,
}: LabelViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.label(
    [
      ...(forId === undefined ? [] : [h.Attribute("for", forId)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(fieldLabelClasses, classes)),
    ],
    children
  );
};

export const controlView = <ParentMessage>({
  id,
  value,
  onInput,
  describedByIds,
  ariaLabel,
  name,
  placeholder,
  type = "text",
  classes,
  style,
  ...state
}: ControlViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();
  const describedBy = describedByIds?.filter((item) => item !== "").join(" ");

  return h.input([
    h.Id(id),
    h.Type(type),
    h.Value(value),
    h.OnInput(onInput),
    ...(name === undefined ? [] : [h.Attribute("name", name)]),
    ...(placeholder === undefined ? [] : [h.Placeholder(placeholder)]),
    ...(describedBy === undefined || describedBy === ""
      ? []
      : [h.Attribute("aria-describedby", describedBy)]),
    ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
    ...(state.invalid === undefined
      ? []
      : [h.Attribute("aria-invalid", state.invalid ? "true" : "false")]),
    ...(state.required === true ? [h.Attribute("required", "")] : []),
    ...(state.disabled === true ? [h.Disabled(true)] : []),
    ...stateAttributes(h, state),
    ...(style === undefined ? [] : [h.Style(style)]),
    h.Class(cn(fieldControlClasses, classes)),
  ]);
};

export const descriptionView = <ParentMessage>({
  id,
  children,
  classes,
  style,
}: DescriptionViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.p(
    [
      ...(id === undefined ? [] : [h.Id(id)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(fieldDescriptionClasses, classes)),
    ],
    children
  );
};

export const errorView = <ParentMessage>({
  id,
  children,
  show,
  classes,
  style,
}: ErrorViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.p(
    [
      ...(id === undefined ? [] : [h.Id(id)]),
      h.Attribute("role", "alert"),
      h.AriaHidden(!show),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(fieldErrorClasses, classes)),
    ],
    show ? children : []
  );
};

export const itemView = <ParentMessage>({
  children,
  classes,
  style,
}: ItemViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(fieldItemClasses, classes)),
    ],
    children
  );
};

export const validityView = <ParentMessage>(
  children: readonly Html[],
  classes?: string
): Html => {
  const h = html<ParentMessage>();

  return h.p(
    [h.Class(cn(fieldValidityClasses, classes))],
    children
  );
};

export const fieldRootClasses = "grid max-w-sm gap-2";

export const fieldLabelClasses = "text-sm font-medium text-gray-950";

export const fieldControlClasses =
  "h-10 rounded-md border border-gray-300 bg-white px-3 text-sm text-gray-950 shadow-sm outline-none transition-colors placeholder:text-gray-400 focus:border-accent-600 focus:ring-2 focus:ring-accent-100 aria-[invalid=true]:border-red-600 aria-[invalid=true]:focus:ring-red-100 disabled:cursor-not-allowed disabled:bg-gray-50 disabled:text-gray-500";

export const fieldDescriptionClasses = "text-sm text-gray-600";

export const fieldErrorClasses = "text-sm font-medium text-red-700";

export const fieldItemClasses = "grid gap-1";

export const fieldValidityClasses = "text-xs text-gray-500";

import { Scene } from "foldkit";
import { html } from "foldkit/html";
import { describe, expect, test } from "vitest";

import * as Field from ".";

const view = (value: string, touched = false) => {
  const h = html<string>();
  const invalid = touched && value === "";
  const errorId = "name-error";
  const descriptionId = "name-description";

  return Field.rootView<string>({
    name: "name",
    required: true,
    invalid,
    touched,
    filled: value !== "",
    children: [
      Field.labelView({ forId: "name", children: [h.span([], ["Name"])] }),
      Field.controlView({
        id: "name",
        ariaLabel: "Name",
        name: "name",
        value,
        onInput: (nextValue) => nextValue,
        placeholder: "Required",
        required: true,
        invalid,
        touched,
        filled: value !== "",
        describedByIds: [errorId, descriptionId],
      }),
      Field.errorView({
        id: errorId,
        show: invalid,
        children: [h.span([], ["Please enter your name"])],
      }),
      Field.descriptionView({
        id: descriptionId,
        children: [h.span([], ["Visible on your profile"])],
      }),
      Field.validityView([h.span([], [invalid ? "Invalid" : "Valid"])]),
    ],
  });
};

describe("Base UI Field registry component", () => {
  test("links label, description, error, and input state", () => {
    Scene.scene(
      {
        update: (model: string, message: string) => [message, []] as const,
        view: (value) => view(value, true),
      },
      Scene.with(""),
      Scene.expect(Scene.role("textbox", { name: "Name" })).toHaveAttr(
        "aria-describedby",
        "name-error name-description"
      ),
      Scene.expect(Scene.role("textbox", { name: "Name" })).toHaveAttr(
        "aria-invalid",
        "true"
      ),
      Scene.expect(Scene.text("Please enter your name")).toExist(),
      Scene.expect(Scene.text("Visible on your profile")).toExist()
    );
  });

  test("omits error content when valid", () => {
    Scene.scene(
      {
        update: (model: string, message: string) => [message, []] as const,
        view: (value) => view(value, true),
      },
      Scene.with("Ada Lovelace"),
      Scene.expect(Scene.role("textbox", { name: "Name" })).toHaveAttr(
        "aria-invalid",
        "false"
      ),
      Scene.expect(Scene.text("Please enter your name")).not.toExist()
    );
  });

  test("exports Base UI state class hooks", () => {
    expect(Field.fieldControlClasses).toContain("aria-[invalid=true]");
    expect(Field.fieldErrorClasses).toContain("text-red");
  });
});
